import Glyph from"./Glyph";import BBox from"./BBox";class COLRLayer{constructor(e,r){this.glyph=e,this.color=r}}export default class COLRGlyph extends Glyph{_getBBox(){let e=new BBox;for(let r=0;r<this.layers.length;r++){let t=this.layers[r].glyph.bbox;e.addPoint(t.minX,t.minY),e.addPoint(t.maxX,t.maxY)}return e}get layers(){let e=this._font.CPAL,r=this._font.COLR,t=0,l=r.baseGlyphRecord.length-1;for(;t<=l;){let e=t+l>>1;var o=r.baseGlyphRecord[e];if(this.id<o.gid)l=e-1;else{if(!(this.id>o.gid)){var s=o;break}t=e+1}}if(null==s){var a=this._font._getBaseGlyph(this.id);return[new COLRLayer(a,h={red:0,green:0,blue:0,alpha:255})]}let i=[];for(let t=s.firstLayerIndex;t<s.firstLayerIndex+s.numLayers;t++){o=r.layerRecords[t];var h=e.colorRecords[o.paletteIndex];a=this._font._getBaseGlyph(o.gid),i.push(new COLRLayer(a,h))}return i}render(e,r){for(let{glyph:t,color:l}of this.layers)e.fillColor([l.red,l.green,l.blue],l.alpha/255*100),t.render(e,r)}}